import React, { useState, useEffect } from 'react';
import Select from 'react-select';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import './Filter.css';

const Filter = ({ medications, adverseEvents, onFilterChange, onExportCSV, filterValues }) => {
  // 受控组件：由父组件传递筛选项和onChange
  const { medication, adverse_event, start_date, end_date } = filterValues;

  // Format date as YYYY-MM-DD for API
  const formatDate = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const handleMedicationChange = (option) => {
    onFilterChange({
      ...filterValues,
      medication: option ? option.value : ''
    });
  };
  const handleAdverseEventChange = (option) => {
    onFilterChange({
      ...filterValues,
      adverse_event: option ? option.value : ''
    });
  };
  const handleStartDateChange = (date) => {
    onFilterChange({
      ...filterValues,
      start_date: date ? formatDate(date) : ''
    });
  };
  const handleEndDateChange = (date) => {
    onFilterChange({
      ...filterValues,
      end_date: date ? formatDate(date) : ''
    });
  };
  const resetFilters = () => {
    onFilterChange({
      medication: '',
      adverse_event: '',
      start_date: '',
      end_date: ''
    });
  };

  // Custom styles for react-select
  const selectStyles = {
    control: (styles) => ({
      ...styles,
      borderRadius: '4px',
      borderColor: '#ced4da',
      boxShadow: 'none',
      '&:hover': {
        borderColor: '#80bdff'
      }
    }),
    menu: (styles) => ({
      ...styles,
      zIndex: 999
    })
  };

  return (
    <div className="filter-container">
      <h2>Filter Data</h2>
      <div className="filter-grid">
        <div className="filter-group">
          <label htmlFor="medication">Filter by Medication</label>
          <Select
            id="medication"
            value={medications.find(m => m.value === medication) || null}
            onChange={handleMedicationChange}
            options={medications}
            placeholder="Select medication..."
            isClearable
            styles={selectStyles}
            className="filter-select"
          />
        </div>
        <div className="filter-group">
          <label htmlFor="adverse-event">Filter by Adverse Event</label>
          <Select
            id="adverse-event"
            value={adverseEvents.find(a => a.value === adverse_event) || null}
            onChange={handleAdverseEventChange}
            options={adverseEvents}
            placeholder="Select adverse event..."
            isClearable
            isSearchable
            styles={selectStyles}
            className="filter-select"
          />
        </div>
        <div className="filter-group">
          <label htmlFor="start-date">From Date</label>
          <DatePicker
            id="start-date"
            selected={start_date ? new Date(start_date) : null}
            onChange={handleStartDateChange}
            selectsStart
            startDate={start_date ? new Date(start_date) : null}
            endDate={end_date ? new Date(end_date) : null}
            maxDate={new Date()}
            placeholderText="Start date"
            className="date-picker"
            dateFormat="yyyy-MM-dd"
          />
        </div>
        <div className="filter-group">
          <label htmlFor="end-date">To Date</label>
          <DatePicker
            id="end-date"
            selected={end_date ? new Date(end_date) : null}
            onChange={handleEndDateChange}
            selectsEnd
            startDate={start_date ? new Date(start_date) : null}
            endDate={end_date ? new Date(end_date) : null}
            minDate={start_date ? new Date(start_date) : null}
            maxDate={new Date()}
            placeholderText="End date"
            className="date-picker"
            dateFormat="yyyy-MM-dd"
          />
        </div>
      </div>
      <div className="filter-actions">
        <button className="btn btn-reset" onClick={resetFilters}>
          Reset Filters
        </button>
        <button className="btn btn-export" onClick={onExportCSV}>
          Export CSV
        </button>
      </div>
    </div>
  );
};

export default Filter;
